<?php get_header(); ?><main><section class="wrap masthead"><div><span class="eyebrow">NOTÍCIAS COM CONTEXTO</span><h1>O essencial do dia.<br>Sem ruído.</h1><p>Política, tecnologia, ciência e esporte com síntese clara, fontes abertas e leitura rápida.</p></div><div class="edition">EDIÇÃO DO DIA<strong><?php echo esc_html(wp_date('d M Y')); ?></strong></div></section><div class="wrap notice"><b>AGORA</b>Seleção editorial com atualização diária e fontes transparentes.</div><section class="wrap news-grid"><?php foreach(franklem_section_data() as $slug=>$section):$q=new WP_Query(['post_type'=>'post','posts_per_page'=>6,'category_name'=>$slug]); ?><section class="news-column" id="<?php echo esc_attr($slug); ?>" style="--section:<?php echo esc_attr($section[1]); ?>"><h2 class="section-heading"><?php echo esc_html($section[0]); ?><span><?php echo esc_html($q->post_count); ?></span></h2><?php if($q->have_posts()):$i=0;while($q->have_posts()):$q->the_post(); ?><article class="story-card"><?php if($i===0&&has_post_thumbnail()): ?><a href="<?php the_permalink(); ?>"><?php the_post_thumbnail('franklem-card'); ?></a><?php endif; ?><span class="time"><?php echo esc_html(human_time_diff(get_the_time('U'),current_time('timestamp'))); ?> atrás</span><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php $sub=franklem_subtitle(); ?><p><?php echo esc_html($sub?:get_the_excerpt()); ?></p><a class="read-more" href="<?php the_permalink(); ?>">Ler notícia →</a></article><?php $i++;endwhile;else: ?><p class="empty">As primeiras notícias desta seção aparecerão aqui.</p><?php endif;wp_reset_postdata(); ?></section><?php endforeach; ?></section><div class="wrap ad-slot">ESPAÇO RESERVADO PARA PUBLICIDADE</div></main><?php get_footer(); ?>
